private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit() && bb.hasRemaining()) {
        int octet = bb.get(i) & 0xFF;
        if (octet <= 0x7F) {
            // one-byte character
            sb.append((char) octet);
            i++;
        } else if (octet <= 0xDF) {
            // two-byte character
            if (bb.remaining() < 2) {
                break;
            }
            int octet2 = bb.get(i + 1) & 0xFF;
            int codepoint = (octet & 0x1F) << 6 | (octet2 & 0x3F);
            sb.append((char) codepoint);
            i += 2;
        } else if (octet <= 0xEF) {
            // three-byte character
            if (bb.remaining() < 3) {
                break;
            }
            int octet2 = bb.get(i + 1) & 0xFF;
            int octet3 = bb.get(i + 2) & 0xFF;
            int codepoint = (octet & 0x0F) << 12 | (octet2 & 0x3F) << 6 | (octet3 & 0x3F);
            sb.append((char) codepoint);
            i += 3;
        } else if (octet <= 0xF7) {
            // four-byte character
            if (bb.remaining() < 4) {
                break;
            }
            int octet2 = bb.get(i + 1) & 0xFF;
            int octet3 = bb.get(i + 2) & 0xFF;
            int octet4 = bb.get(i + 3) & 0xFF;
            int codepoint = (octet & 0x07) << 18 | (octet2 & 0x3F) << 12 | (octet3 & 0x3F) << 6 | (octet4 & 0x3F);
            sb.append((char) codepoint);
            i += 4;
        }
    }
    return i;
}

