/**
* Construct a complete bipartite graph
*/
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Step 1: Create a set of all vertices in the bipartite graph
    Set<V> vertices = new HashSet<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        vertices.add(entry.getValue());
    }

    // Step 2: Create a set of all edges in the bipartite graph
    Set<E> edges = new HashSet<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        for (String neighbor : entry.getKey().neighbors()) {
            if (resultMap.containsKey(neighbor)) {
                E edge = new E(resultMap.get(entry.getKey()), resultMap.get(neighbor));
                edges.add(edge);
            }
        }
    }

    // Step 3: Add vertices and edges to the target graph
    for (V vertex : vertices) {
        target.addVertex(vertex);
    }
    for (E edge : edges) {
        target.addEdge(edge);
    }
}

