public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {

    // Check if the type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the parameterized type and the type arguments
    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] typeArgs = parameterizedType.getActualTypeArguments();

    // Create an array to store the resolved arguments
    Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];

    // Iterate over the type arguments and resolve their arguments
    for (int i = 0; i < typeArgs.length; i++) {
        Type typeArg = typeArgs[i];

        // If the type is a wildcard, get the upper bounds
        if (typeArg instanceof WildcardType) {
            typeArg = ((WildcardType) typeArg).getUpperBounds()[0];
        }

        // If the type is a type variable, try to resolve its arguments
        if (typeArg instanceof TypeVariable) {
            String typeVarName = ((TypeVariable) typeArg).getName();
            resolvedArgs[i] = resolveTypeVariable(typeVarName, targetType);

            // If the type variable cannot be resolved, return null
            if (resolvedArgs[i] == null) {
                return null;
            }
        }

        // If the type is a class, use it directly
        else if (typeArg instanceof Class) {
            resolvedArgs[i] = (Class<?>) typeArg;
        }

        // If the type is not recognized, return null
        else {
            return null;
        }
    }

    return resolvedArgs;
}

