    IndexMappings inputMappings = mappings.getIndexMappings(tableName);

    // Iterate over the fields in the input mappings
    for (String fieldName : inputMappings.getFields().keySet()) {
        // Check if the field exists in the diffMappings
        if (diffMappings.getFields().containsKey(fieldName)) {
            // Get the field mapping from the diffMappings
            FieldMapping fieldMapping = diffMappings.getFields().get(fieldName);

            // Check if the field type is not set in the diffMappings
            if (fieldMapping.getType() == null) {
                // Set the field type to the one in the input mappings
