static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the start date for the current time bucket
    long startDate = timeBucket * dayStep;

    // Get the day of the week for the start date
    int dayOfWeek = (int) ((startDate - startDate) % 7);

    // Check if the day of the week is greater than 1, which means the start date is on the second half of the week
    if (dayOfWeek > 1) {
        // Calculate the end date for the current time bucket
        long endDate = startDate + dayStep - 1;

        // If the end date is on the same week as the start date, return the end date
        if (isSameWeek(startDate, endDate)) {
            return endDate;
        }

        // Otherwise, return the start date
        return startDate;
    }

