  int len = str.length();
  int strPos = 0;
  int bufferPos = lb.size();
  int bytesAdded = 0;
  while (strPos < len) {
    char c = str.charAt(strPos);
    strPos++;
    if (c > 0 && c <= 0x007F) {
      bytesAdded++;
    } else if (c > 0x07FF) {
      bytesAdded += 3;
    } else {
