    if (Graphs.isEmpty(graph)) {
        return false;
    }

    // Check if all vertices are in the graph
    if (!graph.vertexSet().containsAll(vertices)) {
        return false;
    }

    // Check if all edges are present
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    // Check if the graph is connected
    if (!Graphs.isConnected(graph)) {
        return false;
    }

    // Check if the graph is a clique
    return Graphs.isClique(graph);
}
