public List<Integer> computeLowerBounds(List<K> keys) {
    // Create an empty list to store the lower bounds
    List<Integer> lowerBounds = new ArrayList<>(keys.size());

    // Initialize the lower bound for the first key to 0
    int lowerBound = 0;

    // Iterate over the keys and calculate the lower bound for each key
    for (int i = 0; i < keys.size(); i++) {
        // Get the current key
        K key = keys.get(i);

        // Calculate the lower bound for the current key
        lowerBound = Math.max(lowerBound, computeLowerBound(key));

        // Add the lower bound to the list of lower bounds
        lowerBounds.add(lowerBound);
    }

    return lowerBounds;
}
